const crypto = require('crypto');
const http = require('http');
const url = require('url');

// Token verification service behind nginx reverse proxy
// nginx forwards X-Original-URI and handles TLS termination

const HMAC_SECRET = crypto.randomBytes(32);
const SESSION_STORE = new Map();

function constantTimeEqual(a, b) {
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

function createToken(userId, role) {
  const payload = JSON.stringify({ sub: userId, role: role, iat: Date.now() });
  const payloadB64 = Buffer.from(payload).toString('base64url');
  const signature = crypto.createHmac('sha256', HMAC_SECRET)
    .update(payloadB64)
    .digest();
  return `${payloadB64}.${signature.toString('base64url')}`;
}

function verifyToken(token) {
  if (typeof token !== 'string') return null;
  const parts = token.split('.');
  if (parts.length !== 2) return null;

  const [payloadB64, sigB64] = parts;
  const expectedSig = crypto.createHmac('sha256', HMAC_SECRET)
    .update(payloadB64)
    .digest();

  const providedSig = Buffer.from(sigB64, 'base64url');

  if (!constantTimeEqual(expectedSig, providedSig)) {
    return null;
  }

  try {
    return JSON.parse(Buffer.from(payloadB64, 'base64url').toString());
  } catch {
    return null;
  }
}

function extractBearerToken(authHeader) {
  if (!authHeader) return null;
  // Handle array case from duplicate headers (reverse proxy may merge)
  const headerValue = Array.isArray(authHeader) ? authHeader[0] : authHeader;
  if (typeof headerValue !== 'string') return null;
  const match = headerValue.match(/^Bearer\s+(.+)$/i);
  return match ? match[1] : null;
}

// Rate limiting with sliding window
const rateLimits = new Map();
function checkRateLimit(clientIp) {
  const now = Date.now();
  const window = rateLimits.get(clientIp) || [];
  const recent = window.filter(t => now - t < 60000);
  recent.push(now);
  rateLimits.set(clientIp, recent);
  return recent.length <= 100;
}

function getClientIp(req) {
  // Trust X-Forwarded-For from reverse proxy
  const xff = req.headers['x-forwarded-for'];
  if (xff) {
    const ips = (Array.isArray(xff) ? xff[0] : xff).split(',');
    return ips[0].trim();
  }
  return req.socket.remoteAddress;
}

// Authorization check - role hierarchy
function isAuthorized(payload, requiredRole) {
  const roles = { 'viewer': 1, 'editor': 2, 'admin': 3 };
  const userLevel = roles[payload.role];
  const requiredLevel = roles[requiredRole];
  // Type coercion vulnerability: if payload.role is an object with
  // a toString() that returns a valid role, roles[payload.role] uses
  // the string coercion of the key lookup
  if (userLevel === undefined || requiredLevel === undefined) return false;
  return userLevel >= requiredLevel;
}

// Middleware to parse the forwarded request context
function parseProxyContext(req) {
  const originalUri = req.headers['x-original-uri'] || req.url;
  const parsed = url.parse(originalUri, true);
  return {
    path: parsed.pathname,
    query: parsed.query,
    method: req.method
  };
}

// The critical auth endpoint that nginx auth_request calls
const server = http.createServer((req, res) => {
  const clientIp = getClientIp(req);

  if (!checkRateLimit(clientIp)) {
    res.writeHead(429);
    return res.end('Rate limited');
  }

  const context = parseProxyContext(req);

  if (context.path === '/auth/token' && req.method === 'POST') {
    let body = '';
    req.on('data', chunk => { body += chunk; });
    req.on('end', () => {
      try {
        const { username, password } = JSON.parse(body);
        // Simplified auth - in production would check against DB
        if (username === 'admin' && password === process.env.ADMIN_PASS) {
          const token = createToken(username, 'admin');
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ token }));
        } else if (username && password) {
          const token = createToken(username, 'viewer');
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ token }));
        } else {
          res.writeHead(401);
          res.end('Invalid credentials');
        }
      } catch {
        res.writeHead(400);
        res.end('Bad request');
      }
    });
    return;
  }

  // Auth verification endpoint (called by nginx auth_request)
  const token = extractBearerToken(req.headers['authorization']);
  if (!token) {
    res.writeHead(401);
    return res.end('No token');
  }

  const payload = verifyToken(token);
  if (!payload) {
    res.writeHead(401);
    return res.end('Invalid token');
  }

  // Determine required role based on path
  let requiredRole = 'viewer';
  if (context.path && context.path.startsWith('/admin')) {
    requiredRole = 'admin';
  } else if (context.path && context.path.startsWith('/edit')) {
    requiredRole = 'editor';
  }

  // Check authorization using the query parameter override if present
  // This allows the proxy to specify a custom role requirement
  const roleOverride = context.query && context.query.require_role;
  if (roleOverride) {
    requiredRole = roleOverride;
  }

  if (isAuthorized(payload, requiredRole)) {
    res.writeHead(200, {
      'X-Auth-User': payload.sub,
      'X-Auth-Role': payload.role
    });
    res.end('OK');
  } else {
    res.writeHead(403);
    res.end('Forbidden');
  }
});

server.listen(3001, '127.0.0.1', () => {
  console.log('Auth service listening on 127.0.0.1:3001');
});

module.exports = { createToken, verifyToken, isAuthorized, server };
